/**
 * @ohos/dsh-ontology/render — model-facing pinned text, user-facing Markdown,
 * and a small Turtle export.
 *
 * The pinned block is deliberately short: it is injected on every session and
 * whenever a hard constraint changes. Everything else is queried through the
 * `ontology` tool, so the prompt pays for identity/constraints, not the whole
 * graph.
 */

/** Hard cap for the injected block; a user profile that eats the prompt is worse than a missing note. */
export const PINNED_MAX_CHARS = 2000;

/**
 * Render the always-on facts block.
 * @param {object[]} pinned - public facts with `pinned: true`.
 * @param {string} updatedAt - snapshot timestamp.
 * @returns {string} text, or empty when there is nothing to inject.
 */
export function renderPinned(pinned, updatedAt = new Date().toISOString()) {
	const lines = [];
	for (const fact of pinned) {
		const qualifier = fact.qualifier.length > 0 ? ` (${fact.qualifier})` : "";
		lines.push(`- ${fact.subject} · ${fact.predicate} = ${fact.object}${qualifier}`);
	}
	if (lines.length === 0) return "";
	const header = [
		"Known durable facts about the user, from the on-device ontology (authoritative; this snapshot replaces earlier ones).",
		"Do not re-ask these. Use the `ontology` tool to search anything that is not listed.",
		`Snapshot: ${updatedAt}`,
	].join("\n");
	let text = `${header}\n${lines.join("\n")}`;
	if (text.length > PINNED_MAX_CHARS) {
		text = `${text.slice(0, PINNED_MAX_CHARS - 1)}…`;
	}
	return text;
}

/**
 * Render a human-facing Markdown export, grouped by subject.
 * @param {object[]} facts - public facts (live).
 * @param {{counts: object, version: number}} meta - overview data.
 * @param {string} updatedAt - export timestamp.
 * @returns {string} Markdown.
 */
export function renderMarkdown(facts, meta, updatedAt = new Date().toISOString()) {
	const bySubject = new Map();
	for (const fact of facts) {
		const key = fact.subject;
		const rows = bySubject.get(key) ?? [];
		rows.push(fact);
		bySubject.set(key, rows);
	}
	const out = [
		"# 关于我 · 端侧本体",
		"",
		`_更新于 ${updatedAt} · ${meta.counts.facts} 条事实 · ${meta.counts.entities} 个实体 · ${meta.counts.pinned} 条硬约束 · version ${meta.version}_`,
		"",
		"> 这份文件由本机 SQLite 生成，可删除、可导出。带“硬约束”的事实会在每个新会话中自动注入。",
		"",
	];
	for (const [subject, rows] of bySubject) {
		out.push(`## ${subject}`, "");
		for (const fact of rows) {
			const qualifier = fact.qualifier.length > 0 ? ` (${fact.qualifier})` : "";
			const pin = fact.pinned ? " **硬约束**" : "";
			const provenance = fact.source_kind ?? fact.source ?? "model";
			const pending = fact.status === "proposed" ? " · 待确认" : "";
			out.push(`- **${fact.predicate}** = ${fact.object}${qualifier}${pin} · ${fact.observed_at.slice(0, 10)} · ${provenance}${pending}`);
		}
		out.push("");
	}
	return out.join("\n");
}

/** @param {string} value - literal. @returns {string} Turtle-escaped literal. */
function turtleLiteral(value) {
	return `"${String(value).replaceAll("\\", "\\\\").replaceAll('"', '\\"').replaceAll("\n", "\\n")}"`;
}

/**
 * Minimal Turtle export: entities as labelled IRIs, live facts as triples.
 * This is for interchange, not for an OWL reasoner (see docs/ONTOLOGY.md).
 * @param {object[]} facts - public facts.
 * @param {object[]} entities - `{id, kind, name}` rows.
 * @param {string} updatedAt - export timestamp.
 * @returns {string} Turtle text.
 */
export function renderTurtle(facts, entities, updatedAt = new Date().toISOString()) {
	const out = [
		"@prefix ex: <https://harmonygo.local/ontology/> .",
		"@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .",
		"@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .",
		"",
		`# generated ${updatedAt} by HarmonyGo on-device ontology`,
		"",
	];
	for (const entity of entities) {
		out.push(`ex:${entity.id} a ex:${entity.kind} ;`);
		out.push(`  rdfs:label ${turtleLiteral(entity.name)} .`);
	}
	out.push("");
	for (const fact of facts) {
		const subject = `ex:${fact.subject_id}`;
		const predicate = `ex:${fact.predicate}`;
		const object = fact.object_kind === "entity" && fact.object_id !== null
			? `ex:${fact.object_id}`
			: fact.object_kind === "number"
				? `${Number(fact.object)}`
				: fact.object_kind === "bool"
					? `${fact.object === "true"}`
					: fact.object_kind === "date"
						? `${turtleLiteral(fact.object)}^^xsd:date`
						: turtleLiteral(fact.object);
		const qualifier = fact.qualifier.length > 0 ? ` ; ex:qualifier ${turtleLiteral(fact.qualifier)}` : "";
		out.push(`${subject} ${predicate} ${object}${qualifier} .`);
	}
	return `${out.join("\n")}\n`;
}

/**
 * Build the JSON snapshot the app panel reads.
 * @param {object[]} facts - public facts (bounded).
 * @param {{counts: object, pinned: object[], version: number}} overview - overview data.
 * @param {{at: string, ok: boolean, message: string} | null} lastCommand - latest UI command outcome.
 * @param {string} updatedAt - snapshot timestamp.
 * @param {object[]} [deleted] - recent soft-deleted facts.
 * @returns {object} snapshot.
 */
export function buildSnapshot(facts, overview, lastCommand, updatedAt = new Date().toISOString(), deleted = []) {
	return {
		version: overview.version,
		updatedAt,
		counts: overview.counts,
		pinned: overview.pinned,
		facts,
		truncated: overview.counts.facts > facts.length,
		deleted,
		lastCommand: lastCommand ?? null,
	};
}
